// Mobile menu and the photo viewer. The page content itself is static HTML,
// generated by scripts/build.mjs. No dependencies.
(function () {
  "use strict";

  // The <head> sets the "js" class; this tells it the menu is working
  document.documentElement.setAttribute("data-menu", "ready");

  // ---------- Mobile menu ----------
  var toggle = document.querySelector(".nav__toggle");
  var menu = document.getElementById("nav-menu");
  var nav = document.querySelector(".nav");
  var desktop = window.matchMedia("(min-width: 56.25em)");

  function isOpen() { return menu.classList.contains("is-open"); }
  function setMenu(open) {
    toggle.setAttribute("aria-expanded", String(open));
    menu.classList.toggle("is-open", open);
  }

  toggle.addEventListener("click", function () { setMenu(!isOpen()); });
  menu.addEventListener("click", function (e) {
    if (e.target.closest("a")) setMenu(false);
  });
  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape" && isOpen()) {
      setMenu(false);
      toggle.focus();
    }
  });
  // Close when focus or a click moves outside the menu
  nav.addEventListener("focusout", function (e) {
    if (isOpen() && e.relatedTarget && !nav.contains(e.relatedTarget)) setMenu(false);
  });
  document.addEventListener("click", function (e) {
    if (isOpen() && !nav.contains(e.target)) setMenu(false);
  });
  var onBreakpoint = function () { if (desktop.matches) setMenu(false); };
  if (desktop.addEventListener) desktop.addEventListener("change", onBreakpoint);
  else desktop.addListener(onBreakpoint);

  // ---------- Photo viewer (only present when the gallery has photos) ----------
  var dialog = document.querySelector(".lightbox");
  var tiles = Array.prototype.slice.call(document.querySelectorAll("[data-gallery] .work-item__btn"));

  if (dialog && tiles.length && typeof dialog.showModal === "function") {
    var big = dialog.querySelector(".lightbox__img");
    var caption = dialog.querySelector(".lightbox__caption");
    var count = dialog.querySelector(".lightbox__count");
    var closeBtn = dialog.querySelector("[data-close]");
    var current = 0;
    var opener = null;

    var show = function (i) {
      current = (i + tiles.length) % tiles.length;
      var t = tiles[current];
      big.src = t.dataset.full;
      big.alt = t.querySelector("img").alt;
      if (t.dataset.width && t.dataset.height) { big.width = t.dataset.width; big.height = t.dataset.height; }
      caption.textContent = t.dataset.caption || "";
      caption.hidden = !t.dataset.caption;
      count.textContent = tiles.length > 1 ? "Photo " + (current + 1) + " of " + tiles.length : "";
    };

    tiles.forEach(function (btn, i) {
      btn.addEventListener("click", function () {
        opener = btn;
        show(i);
        // showModal() makes the rest of the page inert and keeps focus inside the dialog
        dialog.showModal();
        closeBtn.focus();
      });
    });
    Array.prototype.forEach.call(dialog.querySelectorAll("[data-step]"), function (b) {
      b.addEventListener("click", function () { show(current + Number(b.dataset.step)); });
    });
    closeBtn.addEventListener("click", function () { dialog.close(); });
    // Keep Tab cycling through the viewer's own buttons. showModal() already
    // blocks the page behind, but Chrome would otherwise let focus slip out
    // to the browser's address bar between cycles.
    var controls = Array.prototype.slice.call(dialog.querySelectorAll("button"));
    dialog.addEventListener("keydown", function (e) {
      if (e.key !== "Tab") return;
      var first = controls[0], last = controls[controls.length - 1];
      if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
      else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
    });
    dialog.addEventListener("keydown", function (e) {
      if (tiles.length < 2) return;
      if (e.key === "ArrowLeft") show(current - 1);
      if (e.key === "ArrowRight") show(current + 1);
    });
    // A click on the backdrop (outside the frame) closes the viewer
    dialog.addEventListener("click", function (e) {
      if (e.target === dialog) dialog.close();
    });
    dialog.addEventListener("close", function () {
      if (opener) opener.focus();
    });
  }

  // ---------- Footer year ----------
  var year = document.querySelector("[data-year]");
  if (year) year.textContent = new Date().getFullYear();
})();
